{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회 쿼리의 실행 계획에서 확인한 병목을 근거로 적절한 개선 방식을 선택했는지 검증한다. 실행 계획의 관찰 내용과 개선 방식 사이의 연결에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회 쿼리에 성능 개선이 필요했던 상황이다.",
          "task": "실행 계획에 드러난 병목에 맞는 쿼리 개선 방식을 선택해야 했다.",
          "action": "실행 계획에서 확인한 조회 및 조인 처리 특성을 근거로 개선 방식을 선택한 이유를 설명한다.",
          "result": "선택한 개선 방식이 확인된 병목에 적합했던 이유가 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "실행 계획을 근거로 해당 개선 방식을 선택한 이유",
          "실행 계획에서 실제로 확인한 병목 관련 내용",
          "확인한 병목과 선택한 개선 방식이 연결되는 기술적 설명"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회 시간을 3.2초에서 0.4초로 줄이셨던데요, 실행 계획을 근거로 개선 방식을 고르신 이유는 뭐였어요?",
      "answerTip": "당시 경험을 떠올리며 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획에서 확인한 병목 관련 내용을 구체적으로 제시한다.",
            "선택한 개선 방식이 해당 병목을 줄이는 이유를 기술적으로 타당하게 연결해 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "실행 계획의 관찰 내용과 개선 방식의 관련성은 설명하지만 병목에 대한 설명이 구체적이지 않다.",
            "개선 방식을 선택한 이유는 제시하나 해당 방식이 병목에 작용하는 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "실행 계획에서 무엇을 확인했는지 제시하지 못하고 적용한 방법만 나열한다.",
            "관찰한 병목과 개선 방식의 연결이 없거나 기술적으로 타당하지 않다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "배포 후 발생한 오류를 로그로 추적해 원인을 좁히는 판단을 검증한다. 시간순 로그에서 어떤 사실을 발견했고 그것이 원인 판단의 근거가 되었는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 후 같은 알림이 두 번 발송되는 오류가 발생했다.",
          "task": "시간순으로 모은 로그를 통해 중복 발송의 원인을 좁혀야 했다.",
          "action": "로그에서 확인한 실행 기록의 관계를 설명하고, 그 관찰이 원인 판단으로 이어진 근거를 제시한다.",
          "result": "로그의 관찰 내용으로 뒷받침되는 원인 판단이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "로그에서 원인을 좁히는 데 사용한 구체적인 관찰 내용",
          "시간순 실행 기록 사이에서 확인한 관계",
          "관찰한 로그 내용이 원인 판단으로 이어진 논리적 연결"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송 오류를 추적하셨던데요, 시간순으로 모은 로그에서 무엇을 보고 원인을 좁히셨어요?",
      "answerTip": "기억나는 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "원인을 좁히는 데 사용한 로그의 관찰 내용을 구체적으로 제시한다.",
            "시간순 실행 기록 사이의 관계를 명확히 설명한다.",
            "관찰한 사실이 원인 판단을 뒷받침하는 이유를 논리적으로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "로그에서 확인한 사실과 원인 판단은 제시하지만 실행 기록 사이의 관계가 구체적이지 않다.",
            "관찰 내용과 원인의 연결은 대체로 타당하나 판단 근거의 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "로그에서 확인한 구체적인 사실 없이 원인이나 수정 내용만 제시한다.",
            "실행 기록 사이의 관계를 설명하지 못하거나 관찰 내용으로 원인 판단을 뒷받침하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "여러 요청에서 목적과 필요성을 파악해 구현 범위를 구체화할 수 있는지 검증한다. 세탁소 인터뷰 내용을 요구사항 정의서의 구현 범위로 정한 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 인터뷰에서 서비스에 대한 요구를 수집한 상황이 제시된다.",
          "task": "수집한 요구를 바탕으로 예약 서비스의 구현 범위를 정해야 했던 과제가 드러난다.",
          "action": "인터뷰에서 파악한 요청의 목적과 필요성을 근거로 구현 범위를 구분한 판단을 설명한다.",
          "result": "어떤 요청을 구현 범위에 포함하거나 제외했는지와 그 근거가 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "요구사항 정의서의 구현 범위를 정한 구체적인 근거",
          "그 근거가 된 인터뷰 내용과 요청의 목적",
          "인터뷰 내용이 요청의 포함 또는 제외 결정으로 이어진 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳 인터뷰로 요구사항 정의서를 쓰셨던데요, 구현 범위는 인터뷰의 어떤 내용을 근거로 정하셨어요?",
      "answerTip": "기억나는 사례 하나를 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "구현 범위를 정한 근거를 실제 요청과 연결해 구체적으로 설명한다.",
            "인터뷰에서 파악한 요청의 목적이 명확하게 드러난다.",
            "해당 목적과 근거가 요청의 포함 또는 제외 결정으로 이어지는 논리가 타당하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "구현 범위를 정한 근거는 제시하지만 실제 인터뷰 내용과의 연결이 일부 모호하다.",
            "요청의 목적이나 포함 또는 제외 결정은 드러나지만, 둘 사이의 판단 논리가 충분히 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "인터뷰나 요구사항 정의서 작성 사실만 언급하고 구현 범위를 정한 근거를 설명하지 못한다.",
            "요청의 목적과 구현 범위 결정 사이의 연결을 확인하기 어렵다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황에서도 사용자가 이어갈 수 있는 기능 흐름을 화면 단위로 설계할 수 있는지 검증한다. 화면설계서 작성 경험 중 예외 상황의 화면 흐름에 관한 설계 결정 하나에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "예약 서비스 화면설계서에 반영한 예외 상황 하나가 제시된다.",
          "task": "해당 예외 상황에서 사용자가 보게 될 화면 흐름을 정해야 했던 과제가 드러난다.",
          "action": "예외 발생 전후의 화면 상태와 사용자 동작을 바탕으로 고민한 설계 결정과 그 이유를 설명한다.",
          "result": "선택한 예외 상황의 화면 흐름과 그 설계 판단이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "예외 상황의 화면 흐름에서 가장 고민한 설계 결정",
          "그 결정이 필요했던 예외 상황과 화면 상태",
          "사용자 동작에 따른 화면 흐름을 그렇게 정한 이유"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 화면설계서 28장을 작성하셨던데요, 예외 상황의 화면 흐름에서 가장 고민하신 결정은 뭐였어요?",
      "answerTip": "당시 장면을 떠올리며 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "가장 고민한 설계 결정을 화면 흐름 수준에서 구체적으로 설명한다.",
            "해당 예외 상황과 화면 상태가 분명해 설계 결정의 맥락을 이해할 수 있다.",
            "사용자 동작에 따른 화면 흐름과 그 흐름을 선택한 이유가 타당하게 연결된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황의 설계 결정은 제시하지만 화면 상태나 흐름의 설명이 일부 추상적이다.",
            "설계 이유는 드러나지만 사용자 동작에 따른 화면 흐름과의 연결이 충분하지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "화면설계서의 분량이나 도구 사용만 설명하고 예외 상황의 설계 결정을 제시하지 못한다.",
            "예외 상황과 화면 흐름을 선택한 이유가 불분명해 설계 판단을 확인하기 어렵다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방 확인 과정에서 발견한 이상을 근거로 투약을 보류할 수 있는지 검증한다. 진통제 처방을 확인한 경험에서 투약 중단을 판단한 근거 하나에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방을 투약 전에 확인하던 상황이다.",
          "task": "확인한 처방대로 투약해도 되는지 판단해야 했다.",
          "action": "처방 용량을 비교 기준과 대조하고, 확인된 차이를 근거로 투약 보류 필요성을 판단한 내용을 설명한다.",
          "result": "처방의 어떤 불확실성 때문에 투약을 멈추어야 한다고 판단했는지 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "투약을 멈출 필요가 있다고 판단한 구체적인 근거",
          "처방 용량의 이상 여부를 확인하는 데 사용한 비교 기준과 확인 사실",
          "확인된 차이가 그대로 투약하기 어렵다는 판단으로 이어진 이유"
        ]
      },
      "question": "푸른결종합병원에서 수술 후 환자의 진통제 처방을 확인하셨던데요, 당시 투약을 멈출 필요가 있다고 보신 근거는 무엇이었어요?",
      "answerTip": "당시 상황을 떠올리며 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "투약 보류의 근거를 실제 확인한 처방 내용과 비교 기준으로 구체적으로 설명한다.",
            "확인된 용량 차이가 처방의 정확성을 재확인해야 할 이유가 된다는 연결을 명확히 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "처방 용량의 차이를 투약 보류 근거로 제시하지만, 비교 기준이나 실제 확인 내용이 충분히 구체적이지 않다.",
            "처방 확인이 필요했다는 판단은 드러나지만, 발견한 차이와 투약 보류 사이의 설명이 부분적이다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈춘 근거를 제시하지 못하거나 처방을 주의 깊게 본다는 일반론만 말한다.",
            "무엇과 비교해 이상을 판단했는지 불분명하고, 확인 사실과 투약 보류 판단의 연결이 드러나지 않는다."
          ]
        }
